(1306, NULL, 'DOF', 'SKRE DOF TFMC', 'Aeroporto de Vitória', '{"grupo":"DOF","unidade":"SKRE DOF TFMC","data":"2026-09-22","local":"Aeroporto de Vitória","modal":"Helicóptero ","preposto":"Graziely Caetano ","observacao_nome_arquivo":"","horarios":{"saida_hotel":[{"label1":"Previsto","h1":"08","m1":"30","label2":"Real","h2":"08","m2":"42"}],"embarque_previsto":"10:10","embarque_real":"10:15","atendimento_inicio":"07:43","atendimento_fim":"11:48"},"info_troca":"O atraso na saída de hotel foi devido os&nbsp;<br><div>1.Luckas Neves Da Silva<\/div><div>2.Robson Andrade De Castro.<\/div><div>Que demoraram descer dos quartos e realizar check-out, foram notificados várias vezes.<\/div><div><br><\/div><div>O colaborador terceirizado TFMC<\/div><div>ALAILSON LIMA DA VITORIA não embarcou, pois o nome não constava no voo.<\/div><div>O coordenador de serviço do mesmo, Rodrigo Dornelles informou que a princípio se tudo resolver referente a pendência para embarque.<\/div><div>O colaborador embarcará  amanhã 23\/09.<\/div><div><br><\/div>","pax_embarcando":"\nDOF\n\n1.Pedro Azevedo De Carvalho\n2.Mayane Rebeca Da Silva E Silva\n3.Luckas Neves Da Silva\n4.Leonardo Leal Areias\n5.Adamsky Do Carmo Silva\n6.Maycon Junior Dos Santos\n7.Robson Andrade De Castro\n\nTerceirizado TFMC\n\n1.RAUSENRAUSE COSTA SILVA\n\n","pax_desembarcando":"\n1.Eudes Felipe Da Silva\n2.Jacqueline De Lima Alves\n3.Antonio Ricardo De Araujo Lima\n4.Henrique Cossenza Fournier Pereira\n5.Leandro Pereira Lessa\n6.Gabriel Dos Santos Lima\n7.Carlos Vinicius dos Santos Marinho\n\n","fotos":[]}', 0, NULL, '2026-09-22 21:57:22', '2026-09-22 21:57:23', 'TECHNIP', NULL, 'relatorios_pdf/6ab2f9c3924d9_SKRE_DOF_TFMC_22-09-2026_(10h10).pdf', '177.104.235.82'),
(1307, NULL, 'DOF', 'SKRE DOF TFMC', 'Aeroporto de Vitória', '{"grupo":"DOF","unidade":"SKRE DOF TFMC","data":"2026-09-22","local":"Aeroporto de Vitória","modal":"Helicóptero ","preposto":"Graziely Caetano ","observacao_nome_arquivo":"","horarios":{"saida_hotel":[{"label1":"Previsto","h1":"08","m1":"30","label2":"Real","h2":"08","m2":"42"}],"embarque_previsto":"10:10","embarque_real":"10:15","atendimento_inicio":"07:43","atendimento_fim":"11:48"},"info_troca":"O atraso na saída de hotel foi devido os&nbsp;<div>Colaboradores:<\/div><div><br><div>1.Luckas Neves Da Silva<\/div><div>2.Robson Andrade De Castro.<\/div><div>Que demoraram descer dos quartos e realizar check-out, foram notificados várias vezes.<\/div><div><br><\/div><div>O colaborador terceirizado TFMC<\/div><div>ALAILSON LIMA DA VITORIA não embarcou, pois o nome não constava no voo.<\/div><div>O coordenador de serviço do mesmo, Rodrigo Dornelles informou que a princípio se tudo resolver referente a pendência para embarque.<\/div><div>O colaborador embarcará  amanhã 23\/09.<\/div><div><br><\/div><\/div>","pax_embarcando":"\nDOF\n\n1.Pedro Azevedo De Carvalho\n2.Mayane Rebeca Da Silva E Silva\n3.Luckas Neves Da Silva\n4.Leonardo Leal Areias\n5.Adamsky Do Carmo Silva\n6.Maycon Junior Dos Santos\n7.Robson Andrade De Castro\n\nTerceirizado TFMC\n\n1.RAUSENRAUSE COSTA SILVA\n\n","pax_desembarcando":"\n1.Eudes Felipe Da Silva\n2.Jacqueline De Lima Alves\n3.Antonio Ricardo De Araujo Lima\n4.Henrique Cossenza Fournier Pereira\n5.Leandro Pereira Lessa\n6.Gabriel Dos Santos Lima\n7.Carlos Vinicius dos Santos Marinho\n\n","fotos":[]}', 0, NULL, '2026-09-22 22:03:02', '2026-09-22 22:03:03', 'TECHNIP', NULL, 'relatorios_pdf/6ab2fb177eff7_SKRE_DOF_TFMC_22-09-2026_(10h10).pdf', '177.104.235.82');
